M1_replaceBody_restores_the_local_narrow.to:
const m = content.match(/^---\r?\n[\s\S]*?\r?\n---/);
const leading = m
  ? {
      text: m[0],
      eol: content.startsWith("\r\n", 3) ? "\r\n" : "\n",
      end: m[0].length,
    }
  : null;
if (!leading) return body;
return `${leading.text}${leading.eol}${body}`;

M3_extractBody_restores_the_local_narrow.from:
const leading = FrontmatterService.leadingBlock(content);
if (!leading) return content;
return content
  .slice(leading.end)
  .replace(GroundingExecutor.LEADING_EOL, "");

